import React, { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import WorkerSplash from "./components/WorkerSplash";
import SignIn from "./components/SignIn";

function App() {
  const [view, setView] = useState("splash"); // splash -> signin -> dashboard

  return (
    <div className="bg-[#FFF24D] min-h-screen">
      <AnimatePresence mode="wait">
        {view === "splash" && (
          <motion.div
            key="splash"
            exit={{ opacity: 0, scale: 1.1, filter: "blur(20px)" }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
          >
            <WorkerSplash onComplete={() => setView("signin")} />
          </motion.div>
        )}

        {view === "signin" && (
          <motion.div
            key="signin"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1, ease: [0.16, 1, 0.3, 1] }}
          >
            <SignIn onLogin={() => setView("dashboard")} />
          </motion.div>
        )}

        {view === "dashboard" && (
          <motion.div key="dashboard">
            {/* We will build this next */}
            <div className="h-screen flex items-center justify-center text-[#AB1717] font-black italic text-5xl">
              DASHBOARD_READY
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

export default App;
